WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (246::BIGINT, 'Un crack este profe, incluso siendo la primera vez que da el curso después de muchos años, la única pega fue la basura de asistente que tuvo este semestre.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '233d770226b01b874a7acbb4156b43847a0fd23fe0fdc32e470fc2c181f37d6a'::TEXT, ARRAY[945]::BIGINT[]),
    (246::BIGINT, 'De los mejores profesores que hay en esa asquerosa escuela de Mante.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2026-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'cb2b8842ec2b92ff08b36f6fd59a95efec96041d1a1217c8de8a0d1a1212d020'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Muy buen profesor, explica muy bien y ayuda con muchos rubros extra (eso si, es importante ir y prestarle atención). Hace ejercicios recomendados que ayudan demasido, pero el único problema es que califica duro pero con él se aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Brinda apoyo']::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, '5117a27b6de63436d237410a750932e38dae51cb87fb897afe4cbe5a91c3f737'::TEXT, ARRAY[636]::BIGINT[]),
    (246::BIGINT, 'Extremadamente aburrido. Actitud extraña y confrontativa contra los estudiantes. Los exámenes son innecesariamente complejos y específicos. Da lecturas de muchísimas páginas y al final pregunta cosas pocoimportantes'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-02-15T00:00:00+00:00'::TIMESTAMPTZ, 'eb8631c2c9dadf86927f232fe5a02995d39e827fcdc3461c82009cd01dcb267b'::TEXT, ARRAY[3079]::BIGINT[]),
    (246::BIGINT, 'Buen profesor, explica muy bien y los ejercicios recomendados son muy relevantes. Hace que las clases sean muy amenas y brinda mucho apoyo. La calificación de exámenes es un poco violenta, pero creo que es tema más de la escuela que de otra cosa. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2025-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'bf78bf5cc1ec56408bdcebdca374559b013f199ad614c676028ff42f862b8167'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Es un genio, legalmente sabe mucho y si puede ir a consulta entiende la materia muy bien, los exámenes los hace justos y los quices nada del otro mundo. Ojo!! No menosprecie cuando recomienda realizar algo aunque sea moral, sería una verdadera lástima que no lo haga. xD'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3c98f3aae27ae52299e7c51f15ede980fc7284f3b356bca69a74ad66824f9771'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Uno de los mejores profes de esta puta escuela de mante. Las clases se disfrutan y él hace el curso más ameno. Ayuda mucho si él ve que le pone. Explica muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, '1fda078333267df98b09115f5f1f3a81effef1b09c6ffc68351eaf22c59d65b7'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Este mae es un caso. Un profe complicado de entender. Hace chistes de los que es mejor reírse solo para no caerle mal, es medio bipolar, no le gusta que le falte mucha gente a clase, si pasa ya anda de malas. No haga bromas o se burle de alguien frente a él. No es un curso complicado, pero vaya.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2023-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8c574f40ecdae4e882cc9651b4c61b06156a8d1affbc81c82e8358f8a6a6a56a'::TEXT, ARRAY[2885]::BIGINT[]),
    (246::BIGINT, 'Siento que los comentarios anteriores pueden ser ciertos, pero al menos a lo que yo vi siendo su estudiante, ha evolucionado mucho como persona, se preocupó porque todos pasáramos y siempre estaba anuente a ayudar, siendo un curso difícil hizo su clase lo más amena posible.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '44583e845325017adc1d6eb97612ccfafde297c4b9224b7f03737e022b04632b'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Tiene una actitud bastante extraña y por esta actitud se crea un poco de rechazo a la materia, previo a las clases nadie tiene una actitud positiva hacia él. Los exámenes son bastante difíciles. Pero se puede pasar con ir a consulta'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '627e3608f8e079e1bb1604000ec4c64805348f2265d47530c999b8411b63c236'::TEXT, ARRAY[3079]::BIGINT[]),
    (246::BIGINT, 'Explicó bien la materia del curso mientras la daba, pero ya en los exámenes fue extremadamente específico. Califica duro, y como persona me pareció muy arrogante y sarcástico. El curso se pasa, pero no se disfruta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2023-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'ba75f363c9e9d6d6653d048cc5d9a8e66dd466c8be29a07f5be2ddede20d3bf8'::TEXT, ARRAY[3079]::BIGINT[]),
    (246::BIGINT, 'Es de los que sabe mucho más no sabe explicar. Dice que su metodología es la de "no explicar todo" pero tampoco para que ni siquiera termine de explicar una pieza con softwares que muchos nunca hemos manejado y necesitamos saber la mayoria de comandos posibles ni para que sus clases duren la mitad'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2022-07-26T00:00:00+00:00'::TIMESTAMPTZ, '06184f9c6de48017f305ee2508018ee4b70c272f3b647835880dca59c5fb97b4'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Es buen profesor pero se nota que estuvo alejado de la enseñanza estos años. Quizás en presencial mejoren sus clases'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Exámenes retadores']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'ce845c2599e4fb9b0f69f84d0d171a49451764f255e6cf43cd990e6b700f1e12'::TEXT, ARRAY[636]::BIGINT[]),
    (246::BIGINT, '(Virtual). El profe no explica nada bien, se enreda solo o se "distrae". El curso es muy complicado y aún más con este profe. Es odioso y arrogante. Inspira temor sobre los estudiantes y simplemente dice que el estudiante "no se preparó" si salió mal en alguna evaluacion.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '89c228aeeab0bd14b4b71cf2a5722e29d32e7c86f7924e15bb9b3b7bc8d44984'::TEXT, ARRAY[636]::BIGINT[]),
    (246::BIGINT, 'Pésimo profesor. Puede que sea buen ingeniero, pero como persona no vale nada.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'f37ed76843e1dc94e16ea2b0b1886c512319f76ad48bd390c2f35dc94c6ac825'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Hay que ser autodidacta en este curso y estudiar con el solucionario al lado porque no se da a entender muy bien.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '85c828a3490ab8b06a6bd18567fe1fd9cd01a59ca64b3b69581241b298b38387'::TEXT, ARRAY[931]::BIGINT[]),
    (246::BIGINT, 'Explica muy bien, pero no asegura ir bien ya que el curso por si solo es complicado. En los quices aveces se le pasa la mano de duros jaja, pero si se lleva la materia al día no hay de que preocuparse. Muy buen profe y las clases entretenidas!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '1af16a24ccb215a37a6d3ff1c7d620c9c79348859aa7632030b007b98c9dd913'::TEXT, ARRAY[636]::BIGINT[]),
    (246::BIGINT, 'Una Cochinada de profesor! No lo recomiendo ~!'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('25','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '054ce671c13b82c86812fa75f286f039b16a032f44bf64a37347cb6b0664d948'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Es la primera vez que daba el curso entonces se enredaba un poco, pero se esfuerza bastante porque uno entienda, hace muchos ejemplos, ayuda muchísimo y explica las veces que tenga que explicar. Califica bonito las tareas, y si uno le pone muchísimo exime de los últimos 2 exámenes.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2c29fb7e1fbbe393e562322db96f29c86c70e8e2f86d1b33d8a676dab2e0099c'::TEXT, ARRAY[934]::BIGINT[]),
    (246::BIGINT, 'Muy buena gente! Bien paciente y explica muy bien. Califica un poco duro'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '08c9977b36930310c7393f8b220488af6fccd5607e3b0c883bedc7b4435c9160'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'No es tan bueno pero es llevadero como persona es tuanis aunque a veces intimida , caerle bien seria la mejor opción porque así le va a poner atención pero hay que ponerle mucho es muy exigente'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-27T00:00:00+00:00'::TIMESTAMPTZ, '728b36d59c9f2f929f236a10d88df85890273c16befef2a74424b361b69ed91a'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'El curso con este profesor va a ser difícil pero no por explicar mal, sino por el hecho de que las tareas y quices son complicados, hay que conocer bien la materia para realizarlos, evalúa duro, pero el curso lo pasan los que realmente saben la materia, no regala el curso pero tampoco es imposible.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'aa373103bd7455d3f0656da96e4456ee108e7ca41db70e2165a24c0549c7f708'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Muy buen Ingeniero, sin embargo para lo que es Dibujo es muy malo explicando, califica duro, juega vivo, le gusta llamar la atención. Si usted sabe dibujar y entender las cosas de una manera trivial es su profesor ideal sino es mejor alejarse.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'ef6cc12e8dd76d04215298a794c7c70b919fb68dd404aa5f1264ee141a0d2576'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Buena persona, pero le cuesta mucho darse a entender. No obstante parece ser buen profesional.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, '13b2bb79f015bdc01bcb8673af7db8638d04439d9470fe906378c30957b127f3'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Excelente Profesor, estricto pero con el objetivo de que solo pasen los que puedan dibujar, de cualquier manera explica bastante bien y tiene un gran conocimiento del tema, y deseo de que el estudiante aprenda'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, '6ae72ab1e9593700d2f0b4d818eb518fb63ff83843ecd2fd6124ac97f02be535'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Lo recomiendo solo porque es mejor que llevarlo con Victor Julio.. Pero en sí no le gusta explicar mucho, osea le gusta que el estudiante investigue.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'dbadba64e84c21c4f22b84ea62741a4c49c79d6386727f0a5d32965e4814b13e'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Estricto,no explica bien,ayuda a sus estudiantes,tareas muy difíciles,buen ingeniero mal profesor'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '711e5c76d78457317dafca75f451d4129df01d233add83719f453480cc1fa5a5'::TEXT, ARRAY[610, 933]::BIGINT[]),
    (246::BIGINT, 'Simplemente excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '8656b5530fb38e7367858fa67373fd550eafd6a4dfff372860aef29e90af10b6'::TEXT, ARRAY[1179]::BIGINT[]),
    (246::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'a5d2f2c35007e21e996543c0fb6d93673b1f253253a5f4ede270174bfecfa210'::TEXT, ARRAY[1179, 2141, 611, 1986]::BIGINT[]),
    (246::BIGINT, 'Mal profesor nada recomendado, sabe de dibujo pero no de pedagogía, estricto, tareas difíciles, explicaciones poco claras, si no se tiene conocimientos previos de dibujo no le entenderás nada…'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-25T00:00:00+00:00'::TIMESTAMPTZ, 'c940584a9b8d59e01f2f918d05a508de00339699688b3f38f3f1297e68ca709a'::TEXT, ARRAY[610]::BIGINT[]),
    (246::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-03-14T00:00:00+00:00'::TIMESTAMPTZ, '925a4e7783e821fb04d66979644fb8f6dbbc4d093c14fdd08e6c3e40d1ec1cad'::TEXT, ARRAY[610]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
